function assertNoErrors(errors){if(errors.length)throw Error('BROWSER_PAGE_ERRORS: '+errors.join(';'));}
async function run(name,fn){if(process.env.BROWSER_ONLY&&process.env.BROWSER_ONLY!==name)return;const started=Date.now();try{await fn();results.push({name,passed:true,ms:Date.now()-started});console.log(JSON.stringify(results.at(-1)));}catch(e){results.push({name,passed:false,error:String(e.message).slice(0,1200)});console.error(JSON.stringify(results.at(-1)));throw e;}}
