  await f.page.addInitScript(()=>{const original=window.fetch.bind(window);window.__apiMetrics=[];window.fetch=async(...args)=>{const started=performance.now(),url=new URL(args[0],location.href),query=url.searchParams;const request={route:query.get('route'),method:args[1]?.method??'GET',shape:query.has('id')?(query.has('revision')?'known-revision-read':'content-read'):query.has('includeFolders')?'list-with-folders':query.has('noteId')||query.has('folder')?'scoped-read':'other'};try{const response=await original(...args);window.__apiMetrics.push({...request,durationMs:performance.now()-started,status:response.status});return response;}catch(error){window.__apiMetrics.push({...request,durationMs:performance.now()-started,error:error.name});throw error;}};});
