   const quickTarget=await f.page.locator('.card[data-note]').nth(3).locator('strong').textContent();t=performance.now();await f.page.locator('.card[data-note]').nth(1).click();await f.page.locator('.card[data-note]').nth(2).click();await f.page.locator('.card[data-note]').nth(3).click();await expect(f.page.locator('#title')).toHaveValue(quickTarget);cases.quickSwitch.push(performance.now()-t);api=await f.page.evaluate(()=>window.__apiMetrics.splice(0));requests.push({operation:'quickSwitch',api,server:f.hooks.serverMetrics.splice(0)});
