  const summary=Object.fromEntries(Object.entries(cases).map(([k,v])=>[k,percentile(v)]));await writeFile(new URL('../docs/PERFORMANCE-BASELINE-20261029.json',import.meta.url),JSON.stringify({source:process.env.PERF_SOURCE??'working-tree',browser:'Chromium headless on NAS; API handler + in-memory WebDAV fixture; 20 small notes plus one 128 KiB note; no production Notes',timing:'action wall time; browser fetch time; in-handler server duration; remaining action time includes paint/layout and test harness',summary,requests},null,2)+'\n');console.log(JSON.stringify({name:'current-source-notes-load-baseline',summary}));
