 await run('unsaved-edit-stays-in-memory-and-legacy-draft-database-is-untouched',async()=>{const f=await fixture(1);try{await f.login();await f.page.locator('.card').click();await f.page.evaluate(()=>new Promise((resolve,reject)=>{const request=indexedDB.open('hunghvt-notes-drafts-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('drafts',{keyPath:'key'});request.onsuccess=()=>{const db=request.result,tx=db.transaction('drafts','readwrite');tx.objectStore('drafts').put({key:'synthetic-legacy-record',note:{text:'fixture untouched'}});tx.oncomplete=()=>{db.close();resolve();};tx.onerror=()=>reject(tx.error);};request.onerror=()=>reject(request.error);}));await f.page.evaluate(()=>{window.__draftDbAccesses=0;const original=IDBFactory.prototype.open;IDBFactory.prototype.open=function(name,...args){if(name==='hunghvt-notes-drafts-v1')window.__draftDbAccesses++;return original.call(this,name,...args);};});await f.context.setOffline(true);await f.page.locator('#text').fill('Chưa lưu, còn trong phiên này');await f.page.locator('#save').click();await expect(f.page.locator('#save-status')).toHaveAttribute('data-state','error');await expect(f.page.locator('#global-status')).toContainText('còn trong phiên trang này');expect(await f.page.evaluate(()=>window.__draftDbAccesses)).toBe(0);const savesBeforeClose=f.hooks.posts.length;f.hooks.onDialog=async d=>d.dismiss();await f.page.locator('#close-editor').click();await expect.poll(()=>f.hooks.dialogs.length).toBeGreaterThan(0);expect(await f.page.locator('#editor').isVisible()).toBe(true);expect(await f.page.locator('#text').inputValue()).toBe('Chưa lưu, còn trong phiên này');expect(f.hooks.posts.length).toBe(savesBeforeClose);const reload=f.page.reload().catch(()=>null);await expect.poll(()=>f.hooks.dialogs.length).toBeGreaterThan(0);await f.page.waitForTimeout(50);expect(await f.page.locator('#text').inputValue()).toBe('Chưa lưu, còn trong phiên này');f.hooks.onDialog=null;await f.page.evaluate(()=>{window.__draftDbAccesses=0;});await f.context.setOffline(false);await f.page.locator('#save').click();await expect(f.page.locator('#save-status')).toHaveAttribute('data-state','saved');expect((await f.store.get(f.ids[0])).text).toBe('Chưa lưu, còn trong phiên này');expect(await f.page.evaluate(()=>window.__draftDbAccesses)).toBe(0);const legacy=await f.page.evaluate(()=>new Promise((resolve,reject)=>{const request=indexedDB.open('hunghvt-notes-drafts-v1');request.onsuccess=()=>{const db=request.result,tx=db.transaction('drafts','readonly'),get=tx.objectStore('drafts').get('synthetic-legacy-record');get.onsuccess=()=>{db.close();resolve(get.result);};get.onerror=()=>reject(get.error);};request.onerror=()=>reject(request.error);}));expect(legacy.note.text).toBe('fixture untouched');}finally{await f.done();}});

